#!/usr/bin/env python3
"""Render the Waltzman living-world demo from canonical projection bundles."""

from __future__ import annotations

import json
from html import escape
from typing import Any


def render_html(runs: dict[str, dict[str, Any]]) -> str:
    if set(runs) != {"baseline", "intervention"}:
        raise ValueError("Waltzman renderer expects baseline and intervention branches")
    payload = json.dumps(runs, sort_keys=True, separators=(",", ":")).replace("</", "<\\/")
    world_id = escape(runs["baseline"]["world_id"])
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Waltzman Coordination Lab · World Substrate</title>
<script src="https://unpkg.com/deck.gl@9.4.0/dist.min.js"></script>
<style>
:root{{--bg:#091019;--panel:#111b27;--card:#172333;--card2:#1d2c3e;--text:#edf5ff;--muted:#91a4ba;--line:#2c4057;--accent:#77aaff;--info:#66d2e6;--causal:#ff9b76;--resource:#8ed18b;--authority:#c89cf1;--analysis:#ffd16a;--ok:#79d8aa;--warn:#f1c86b;--danger:#ef8c82}}
*{{box-sizing:border-box}}html,body{{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}}button,select,input{{font:inherit}}button{{color:inherit}}.shell{{max-width:1540px;margin:auto;padding:20px}}.top{{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:12px}}.eyebrow{{font-size:10px;letter-spacing:.16em;text-transform:uppercase;font-weight:850;color:#8ba6c2}}h1{{font-size:25px;margin:5px 0}}.top p{{max-width:900px;color:var(--muted);font-size:12px;line-height:1.55;margin:0}}.truth{{border:1px solid #395574;border-radius:999px;padding:8px 11px;color:#a9c5e3;font-size:10px;white-space:nowrap}}.panel{{background:var(--panel);border:1px solid var(--line);border-radius:15px}}.controls{{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:11px;margin-bottom:11px}}.btn,.select{{height:38px;border:1px solid var(--line);background:var(--card);border-radius:10px;padding:0 12px;font-weight:750;font-size:11px;cursor:pointer}}.btn.primary{{background:#28466d;border-color:#4b79b4}}.btn[aria-pressed="true"]{{border-color:var(--accent);background:#213a56}}.select{{color:var(--text)}}.branch-label{{font-size:9px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.1em}}.grow{{flex:1}}.scrub{{width:min(460px,100%);accent-color:var(--accent)}}.workspace{{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(310px,.68fr);gap:11px}}.map-panel{{padding:11px;min-width:0}}.map-head{{display:flex;justify-content:space-between;gap:12px;padding:2px 2px 9px}}.map-head strong{{font-size:12px}}.map-head small{{display:block;color:var(--muted);font-size:9px;margin-top:3px}}.world{{position:relative;min-height:650px;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:radial-gradient(circle at 50% 45%,#172334 0,#101a27 48%,#0d1621 100%)}}.world:before{{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.022) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.022) 1px,transparent 1px);background-size:30px 30px}}#deck{{position:absolute;inset:0;z-index:4}}#deck canvas{{position:absolute!important;inset:0}}.hall{{position:absolute;left:30%;top:27%;width:40%;height:46%;border:2px dashed #344e6a;border-radius:28px;background:rgba(18,31,45,.55);z-index:1}}.hall-label{{position:absolute;left:50%;top:29%;transform:translateX(-50%);font-size:10px;color:#7590aa;z-index:2}}.authority{{position:absolute;left:37%;top:58%;width:26%;height:20%;border:2px dashed var(--authority);border-radius:18px;z-index:3;pointer-events:none}}.node{{position:absolute;z-index:10;transform:translate(-50%,-50%);transition:left .35s,top .35s}}.resident{{width:48px;height:48px;border-radius:50%;border:3px solid #0d1621;background:#25384e;display:grid;place-items:center;font-weight:900;font-size:15px;box-shadow:0 6px 18px #0008}}.resident.conditional{{outline:2px solid var(--warn);outline-offset:2px}}.resident.support{{outline:2px solid var(--ok);outline-offset:2px}}.node-label{{position:absolute;top:54px;left:50%;transform:translateX(-50%);white-space:nowrap;text-align:center;font-size:9px;font-weight:800}}.node-label small{{display:block;color:var(--muted);font-size:8px;font-weight:500;margin-top:2px}}.resource-card{{position:absolute;z-index:8;transform:translate(-50%,-50%);min-width:130px;background:rgba(23,35,51,.94);border:1px solid #3f6247;border-radius:11px;padding:8px;font-size:9px}}.resource-card strong{{display:block;font-size:10px}}.resource-card span{{color:#b6d8b5;display:block;margin-top:3px}}.institution-card{{position:absolute;z-index:9;transform:translate(-50%,-50%);background:#1c2634;border:1px solid #765e99;border-radius:12px;padding:9px;min-width:145px;text-align:center;font-size:9px}}.institution-card strong{{font-size:11px;display:block}}.activity-card{{position:absolute;z-index:8;transform:translate(-50%,-50%);border:1px solid #54708d;background:#162435;border-radius:10px;padding:7px 9px;font-size:9px}}.package-card{{position:absolute;z-index:8;transform:translate(-50%,-50%);border:1px solid #796c42;background:#2a2618;border-radius:10px;padding:7px 9px;font-size:9px}}svg.edges{{position:absolute;inset:0;width:100%;height:100%;z-index:6;pointer-events:none}}.info-edge{{stroke:var(--info);stroke-width:2.5;stroke-dasharray:8 7;fill:none;opacity:.9}}.causal-edge{{stroke:var(--causal);stroke-width:3;fill:none;opacity:.88}}.speech{{position:absolute;z-index:18;max-width:240px;border:1px solid #477085;background:#17283a;border-radius:12px;padding:8px 10px;font-size:9px;line-height:1.4;box-shadow:0 8px 25px #0008}}.sidebar{{display:grid;gap:11px;align-content:start}}.side{{padding:12px}}.side h2{{font-size:11px;margin:0 0 8px}}.metrics{{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}}.metric{{background:var(--card);border:1px solid var(--line);border-radius:9px;padding:8px}}.metric span{{display:block;color:var(--muted);font-size:8px}}.metric strong{{display:block;font-size:12px;margin-top:3px}}.current{{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px;font-size:10px;line-height:1.45}}.current .id{{font-family:ui-monospace,monospace;font-size:8px;color:#8399b1;margin-top:6px}}.evidence-grid{{display:grid;grid-template-columns:1fr;gap:7px;margin-top:8px}}.evidence{{border-radius:9px;padding:8px;font-size:9px;line-height:1.42;background:var(--card)}}.evidence.info{{border:1px solid #366875}}.evidence.causal{{border:1px solid #7e5547}}.evidence strong{{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:4px}}.eventlist{{display:grid;gap:5px;max-height:250px;overflow:auto}}.event{{border:1px solid var(--line);background:var(--card);border-radius:8px;padding:7px;text-align:left;cursor:pointer;font-size:8px}}.event.active{{border-color:var(--accent);background:#20354e}}.event strong{{font-size:9px}}.event span{{color:var(--muted);float:right}}.analysis{{border-color:#65572b;background:#221f14}}.analysis-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}}.analysis .metric{{border-color:#62562f}}.adequacy{{margin-top:11px;padding:12px}}.adequacy-head{{display:flex;justify-content:space-between;align-items:center;gap:10px}}.badge{{border-radius:999px;padding:4px 7px;font-size:8px;border:1px solid #3d654c;color:#9fddb1}}.depgrid{{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:9px}}.dep{{border:1px solid var(--line);background:var(--card);border-radius:9px;padding:7px;font-size:8px;line-height:1.35}}.dep strong{{display:block;font-size:8px;margin-bottom:3px}}.risk{{margin-top:8px;color:var(--muted);font-size:8px;line-height:1.45}}.fork{{font-size:9px;color:#b8c9db}}.footer{{color:#6f849a;font-size:8px;line-height:1.5;margin:9px 2px}}[hidden]{{display:none!important}}@media(max-width:980px){{.workspace{{grid-template-columns:1fr}}.world{{min-height:590px}}.depgrid{{grid-template-columns:repeat(2,1fr)}}}}@media(max-width:600px){{.shell{{padding:10px}}.top{{display:block}}.truth{{display:inline-block;margin-top:9px}}.world{{min-height:540px}}.depgrid{{grid-template-columns:1fr}}}}
</style></head><body><main class="shell">
<header class="top"><div><div class="eyebrow">World Substrate demo · Waltzman reference world</div><h1>World Substrate: executable coordination world</h1><p>This World Substrate client replays one canonical world from its initial snapshot and retained event deltas. Information lineage, cognition context evidence, hard causal ancestry, and Waltzman-style analysis are shown as different layers rather than collapsed into one narrative.</p></div><div class="truth">canonical world: {world_id}</div></header>
<section class="panel controls"><span class="branch-label">Branch</span><select id="branch" class="select"><option value="baseline">Baseline · blocked</option><option value="intervention">Intervention · recovers</option></select><button id="play" class="btn primary">❚❚ Pause</button><button id="step" class="btn">Step</button><button id="reset" class="btn">Reset</button><button class="btn toggle" data-layer="information" aria-pressed="true">📡 Information</button><button class="btn toggle" data-layer="causal" aria-pressed="true">⛓ Causal</button><button class="btn toggle" data-layer="resources" aria-pressed="true">◫ Constraints</button><button class="btn toggle" data-layer="analysis" aria-pressed="true">△ Waltzman</button><span class="grow"></span><span id="fork" class="fork"></span><input id="scrub" class="scrub" type="range" min="-1" value="-1" aria-label="event timeline"></section>
<div class="workspace"><section class="panel map-panel"><div class="map-head"><div><strong>Living coordination world</strong><small id="clock">tick 0 · revision 0 · initial state</small></div><div id="layers" style="font-size:9px;color:var(--muted)">information · causal · constraints · Waltzman</div></div><div id="world" class="world"><div class="hall"></div><div class="hall-label">COORDINATION HALL</div><div id="deck" aria-label="deck.gl schematic world"></div><div id="authority" class="authority"></div><svg id="edges" class="edges"></svg><div id="nodes"></div><div id="speech" class="speech" hidden></div></div></section>
<aside class="sidebar"><section class="panel side"><h2>World state</h2><div class="metrics"><div class="metric"><span>Coalition</span><strong id="coalition">ready</strong></div><div class="metric"><span>Meeting</span><strong id="meeting">pending</strong></div><div class="metric"><span>Support</span><strong id="support">6 / 6</strong></div><div class="metric"><span>Branch</span><strong id="branchMetric">baseline</strong></div></div></section>
<section class="panel side"><h2>Selected canonical event</h2><div id="current" class="current"></div><div class="evidence-grid"><div class="evidence info"><strong>Information / cognition context</strong><div id="context">none</div></div><div class="evidence causal"><strong>Mechanic-declared causal parents</strong><div id="parents">none declared</div></div></div></section>
<section id="analysisPanel" class="panel side analysis"><h2>Detachable Waltzman analysis</h2><div class="analysis-grid"><div class="metric"><span>Trust proxy</span><strong id="trust">—</strong></div><div class="metric"><span>Risk proxy</span><strong id="risk">—</strong></div><div class="metric"><span>Readiness</span><strong id="readiness">—</strong></div></div><div id="analysisNote" class="risk"></div></section>
<section class="panel side"><div style="display:flex;justify-content:space-between"><h2>Retained events</h2><span style="font-size:8px;color:var(--muted)">click to scrub</span></div><div id="events" class="eventlist"></div></section></aside></div>
<section class="panel adequacy"><div class="adequacy-head"><div><strong style="font-size:11px">Bounded dependency mapping</strong><div style="font-size:8px;color:var(--muted);margin-top:3px">Declared consequential assumptions mapped to installed mechanics, plus residual risk. Not counterfactual proof.</div></div><span id="adequacyBadge" class="badge"></span></div><div id="depgrid" class="depgrid"></div><div id="residual" class="risk"></div></section>
<div class="footer">Presentation controls never write canonical state. Waltzman metrics are detachable analysis. A delivered message can appear as cognition context without being promoted to hard causal ancestry. Event IDs, revisions, changes, and parent IDs come from the retained Engine trace.</div>
</main><script>
const RUNS={payload};
let branch='baseline',idx=-1,playing=true,timer=null,deckView=null;const layers={{information:true,causal:true,resources:true,analysis:true}};
const $=id=>document.getElementById(id), deep=x=>JSON.parse(JSON.stringify(x));
function ensureDeck(){{if(deckView||!window.deck)return deckView;deckView=new deck.Deck({{parent:$('deck'),views:new deck.OrthographicView({{id:'waltzman-ortho',flipY:true}}),initialViewState:{{target:[50,50,0],zoom:3}},controller:false,layers:[],getTooltip:({{object}})=>object?.tooltip||null}});return deckView}}
function deckLayers(run,m){{if(!ensureDeck())return [];const residents=['mara','ari','tomas','nira','idris','selene'].map(id=>{{const e=m.entities[id],p=pos(run,id),stance=e.components.commitment?.stance||'monitoring';return {{id,label:e.label,glyph:run.scene.resident_glyphs[id],stance,position:[p.x,p.y],tooltip:`${{e.label}} · ${{stance}}`}}}});const utterances=[];if(layers.information)for(const infoEntity of activeInfo(m).filter(x=>x.category_ids.includes('utterance'))){{const info=infoEntity.components.information;for(const dEntity of deliveries(m)){{const d=dEntity.components.delivery;if(d.info_id!==infoEntity.entity_id||!run.scene.positions[info.source_id]||!run.scene.positions[d.recipient_id])continue;utterances.push({{source:[pos(run,info.source_id).x,pos(run,info.source_id).y],target:[pos(run,d.recipient_id).x,pos(run,d.recipient_id).y],tooltip:`${{info.source_id}} → ${{d.recipient_id}}: ${{info.content}}`}})}}}}return [new deck.LineLayer({{id:'information-lines',data:utterances,getSourcePosition:d=>d.source,getTargetPosition:d=>d.target,getColor:[102,210,230,220],getWidth:2,widthUnits:'pixels',pickable:true}}),new deck.ScatterplotLayer({{id:'residents',data:residents,getPosition:d=>d.position,getRadius:22,radiusUnits:'pixels',getFillColor:d=>d.stance==='conditional'?[241,200,107,235]:d.stance==='support'?[121,216,170,235]:[119,170,255,235],getLineColor:[9,16,25,255],lineWidthMinPixels:3,stroked:true,pickable:true}}),new deck.TextLayer({{id:'resident-labels',data:residents,getPosition:d=>d.position,getText:d=>`${{d.glyph}}  ${{d.label}}
${{d.stance}}`,getColor:[237,245,255,255],getSize:11,sizeUnits:'pixels',getTextAnchor:'middle',getAlignmentBaseline:'top',getPixelOffset:[0,28],fontFamily:'Inter, system-ui, sans-serif'}})]}}
function renderDeck(run,m){{const d=ensureDeck();if(d)d.setProps({{layers:deckLayers(run,m)}})}}
function applyChange(root,ch){{let c=root;const p=ch.path.split('.');for(let i=0;i<p.length-1;i++)c=c[p[i]];c[p[p.length-1]]=deep(ch.after)}}
function materialAt(run,j){{const m=deep(run.initial_snapshot.world);for(let k=0;k<=j;k++)for(const ch of run.events[k].changes)applyChange(m,ch);return m}}
function comps(m,id){{return m.entities[id]?.components||{{}}}}function pos(run,id){{return run.scene.positions[id]||{{x:50,y:50}}}}
function pct(n){{return Math.round(Number(n)*100)+'%'}}
function activeInfo(m){{return Object.values(m.entities).filter(e=>e.components?.information?.active===true)}}
function deliveries(m){{return Object.values(m.entities).filter(e=>e.components?.delivery?.status==='delivered')}}
function annotation(run,e){{return e?run.annotations[e.event_id]||{{title:e.rule_id,detail:e.rule_id}}:{{title:'Initial world',detail:'No transition selected.'}}}}
function nodeDiv(cls,id,x,y,html){{return `<div class="node ${{cls}}" data-id="${{id}}" style="left:${{x}}%;top:${{y}}%">${{html}}</div>`}}
function resourceCard(id,p,label,value){{return `<div class="resource-card" style="left:${{p.x}}%;top:${{p.y}}%"><strong>${{label}}</strong><span>${{value}}</span></div>`}}
function renderWorld(run,m,e){{let html='';const residents=['mara','ari','tomas','nira','idris','selene'];if(!ensureDeck())for(const id of residents){{const e0=m.entities[id],p=pos(run,id),c=e0.components.commitment,s=c?.stance||'monitoring';html+=nodeDiv('resident '+s,id,p.x,p.y,`${{run.scene.resident_glyphs[id]}}<div class="node-label">${{e0.label}}<small>${{s}}</small></div>`)}}
if(layers.resources){{for(const id of ['validation-capacity','clinical-staff','shared-reserve']){{const r=comps(m,id).resource,p=pos(run,id);html+=resourceCard(id,p,m.entities[id].label,`${{r.current}} / ${{r.required}} ${{r.unit}}`)}}const sg=comps(m,'safeguard-record').constraint,p=pos(run,'safeguard-record');html+=resourceCard('safeguard-record',p,'Safeguard',sg.status);}}
const inst=comps(m,'coalition-hub').institution,ip=pos(run,'coalition-hub');html+=`<div class="institution-card" style="left:${{ip.x}}%;top:${{ip.y}}%"><strong>Coalition: ${{inst.status}}</strong>${{inst.support_count}} support · ${{inst.conditional_count}} conditional</div>`;const act=comps(m,'coordination-meeting').activity,ap=pos(run,'coordination-meeting');html+=`<div class="activity-card" style="left:${{ap.x}}%;top:${{ap.y}}%">Meeting · ${{act.status}}${{act.end_tick!==null?' · ends t'+act.end_tick:''}}</div>`;const pack=comps(m,'stabilization-package').package,pp=pos(run,'stabilization-package');html+=`<div class="package-card" style="left:${{pp.x}}%;top:${{pp.y}}%">Stabilization package · ${{pack.status}}</div>`;$('nodes').innerHTML=html;
renderDeck(run,m);const svg=$('edges');svg.hidden=Boolean(deckView);svg.innerHTML='';if(!deckView&&layers.information){{for(const infoEntity of activeInfo(m).filter(x=>x.category_ids.includes('utterance'))){{const info=infoEntity.components.information;for(const dEntity of deliveries(m)){{const d=dEntity.components.delivery;if(d.info_id!==infoEntity.entity_id)continue;if(!run.scene.positions[info.source_id]||!run.scene.positions[d.recipient_id])continue;const a=pos(run,info.source_id),b=pos(run,d.recipient_id);const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',a.x+'%');line.setAttribute('y1',a.y+'%');line.setAttribute('x2',b.x+'%');line.setAttribute('y2',b.y+'%');line.setAttribute('class','info-edge');svg.appendChild(line)}}}}}}
$('authority').hidden=!layers.causal;const sp=$('speech'),ann=annotation(run,e);if(e&&ann.kind==='information'){{const src=e.causal_bearer?.id;if(src&&run.scene.positions[src]){{const p=pos(run,src);sp.style.left=`calc(${{p.x}}% + 24px)`;sp.style.top=`calc(${{p.y}}% - 70px)`;sp.textContent=ann.detail;sp.hidden=false}}else sp.hidden=true}}else sp.hidden=true}}
function renderEvent(run,e){{const ann=annotation(run,e);$('current').innerHTML=`<strong>${{ann.title}}</strong><div style="margin-top:5px">${{ann.detail}}</div><div class="id">${{e?e.event_id+' · '+e.rule_id+' · '+e.status:'initial snapshot'}}</div>`;const ctx=e?.information_context||[];$('context').innerHTML=ctx.length?ctx.map(x=>`<div><strong>${{x.info_id}}</strong> · ${{x.topic||'information'}}</div>`).join(''):'none retained for this event';const parents=e?.causal_parent_event_ids;$('parents').innerHTML=parents?.length?parents.map(id=>`<div><strong>${{id}}</strong> · ${{run.annotations[id]?.title||'retained parent'}}</div>`).join(''):'none declared';}}
function renderList(run){{$('events').innerHTML=run.events.map((e,j)=>{{const a=annotation(run,e);return `<button class="event ${{j===idx?'active':''}}" data-j="${{j}}"><strong>${{e.event_id}}</strong><span>t${{e.tick}}</span><div style="margin-top:3px">${{a.title}}</div></button>`}}).join('');document.querySelectorAll('[data-j]').forEach(b=>b.onclick=()=>{{stop();idx=Number(b.dataset.j);render()}})}}
function renderAnalysis(run,e){{const key=e?.event_id||'initial',a=run.analysis?.[key];$('analysisPanel').hidden=!layers.analysis;if(!a)return;$('trust').textContent=pct(a.trust_proxy);$('risk').textContent=pct(a.perceived_risk_proxy);$('readiness').textContent=pct(a.coordination_readiness_proxy);$('analysisNote').textContent='Observer-only heuristics · '+a.institution_status+' · '+a.unsatisfied_constraints.length+' unsatisfied prerequisite(s).'}}
function renderAdequacy(run){{const a=run.adequacy;$('adequacyBadge').textContent=`${{a.summary.mapped}} mapped · ${{a.summary.unmapped}} unmapped`;$('depgrid').innerHTML=a.dependencies.map(d=>`<div class="dep"><strong>${{d.mapping_status==='mapped'?'✓':'!'}} ${{d.id}}</strong>${{d.claim}}</div>`).join('');$('residual').innerHTML='<strong>Interpretation:</strong> '+a.interpretation+'<br><strong>Residual risk:</strong> '+a.residual_risk.join(' · ')}}
function render(){{const run=RUNS[branch],e=idx>=0?run.events[idx]:null,m=materialAt(run,idx);$('scrub').max=String(run.events.length-1);$('scrub').value=String(idx);$('clock').textContent=`tick ${{m.tick}} · revision ${{m.revision}} · ${{e?e.event_id:'initial state'}}`;const inst=comps(m,'coalition-hub').institution,act=comps(m,'coordination-meeting').activity;$('coalition').textContent=inst.status;$('meeting').textContent=act.status;$('support').textContent=`${{inst.support_count}} / ${{inst.required_support}}`;$('branchMetric').textContent=branch;$('fork').textContent=branch==='baseline'?`fork point: ${{run.fork.fork_event_id}}`:`forked after ${{run.fork.shared_event_count}} retained events`;renderWorld(run,m,e);renderEvent(run,e);renderList(run);renderAnalysis(run,e);renderAdequacy(run);$('layers').textContent=Object.entries(layers).filter(x=>x[1]).map(x=>x[0]).join(' · ')||'base world only';document.querySelectorAll('.toggle').forEach(b=>b.setAttribute('aria-pressed',String(layers[b.dataset.layer])))}}
function stop(){{playing=false;clearInterval(timer);timer=null;$('play').textContent='▶ Play'}}function start(){{playing=true;clearInterval(timer);$('play').textContent='❚❚ Pause';timer=setInterval(()=>{{const n=RUNS[branch].events.length;idx=idx>=n-1?-1:idx+1;render()}},1000)}}
$('play').onclick=()=>playing?stop():start();$('step').onclick=()=>{{stop();const n=RUNS[branch].events.length;idx=Math.min(n-1,idx+1);render()}};$('reset').onclick=()=>{{stop();idx=-1;render()}};$('branch').onchange=e=>{{stop();branch=e.target.value;idx=-1;render()}};$('scrub').oninput=e=>{{stop();idx=Number(e.target.value);render()}};document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>{{layers[b.dataset.layer]=!layers[b.dataset.layer];render()}});render();start();
</script></body></html>'''
